"""Builds reports/D0_OPEN_ROLL.md and figures/bl_d0z_summary.png from bl_d0z_* outputs; recomputes the coverage table (minute-0 buy-backs as their own class; roll-out and opening long buys re-tiered from the tests)."""
import sys, os, json, warnings; sys.path.insert(0, '.'); warnings.filterwarnings('ignore')
import numpy as np, pandas as pd, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
from bl_common import OUT
RP = os.path.join(os.path.dirname(OUT), 'reports'); FIG = os.path.join(RP, 'figures')
def _md(self, index=True, **kw):
    d = self.reset_index() if index else self
    h = '| ' + ' | '.join(str(c) for c in d.columns) + ' |\n|' + '---|' * len(d.columns) + '\n'
    f = lambda v: ('' if pd.isna(v) else (f'{v:g}' if isinstance(v, (float, np.floating)) else str(v)))
    return h + '\n'.join('| ' + ' | '.join(f(v) for v in r) + ' |' for r in d.itertuples(index=False))
pd.DataFrame.to_markdown = _md
rd = lambda n: pd.read_csv(f'{OUT}/{n}.csv'); J = lambda n: json.load(open(f'{OUT}/bl_summary_{n}.json'))
AUD, GATE, GAIN, RA, POST = rd('bl_d0z_audit'), rd('bl_d0z_roll_gate'), rd('bl_d0z_roll_gain'), rd('bl_d0z_roll_auc'), rd('bl_d0z_post'); OL, OR_, OC, OS, OLG, SQ, GP = rd('bl_d0z_open_lots'), rd('bl_d0z_open_rule'), rd('bl_d0z_open_count'), rd('bl_d0z_open_sells'), rd('bl_d0z_open_longs'), rd('bl_d0z_open_seq'), rd('bl_d0z_open_gap')
R1, R2 = J('d0z1'), J('d0z2'); LL, CELLS, CV0 = rd('bl_d0z_open_lotlevel'), rd('bl_d0z_open_cells'), rd('bl_d0w_coverage'); pc = lambda x, d=1: f'{100 * x:.{d}f}%'
D = pd.read_pickle(f'{OUT}/bl_d0u_orders.pkl.gz'); X = pd.read_pickle(f'{OUT}/bl_d0y_lots.pkl.gz'); TOT = float(D.lots.sum()); clsl = D.groupby('klass').lots.sum()
pre = POST[(POST.outcome == 'roll-out') & (POST.set == 'REF + sale clock')].iloc[0]; oth = GATE[GATE.outcome == 'other'].iloc[0]; ref_roll = RA[(RA.outcome == 'roll-out') & RA.set.str.startswith('REF (')].iloc[0]; gain = GAIN[GAIN.outcome == 'roll-out'].iloc[0]; othpost = POST[(POST.outcome == 'other') & POST.set.str.startswith('POST')].iloc[0]
roll_met = bool(pre.gate == 'met')
# ---- coverage recomputed
CV = CV0.copy(); CV['tier_before'] = CV0.tier_after; scale = clsl['body buy-back'] / len(X); X['t'] = X.type.astype(str).str.slice(0, 2).str.strip(); j0 = X[X.j == 0].t.value_counts(); nmap = {'1': 'cycle-stop window', '6': 'roll-out', '7': 'burst member', '3': 'stop-loss', '5': 'partner', '8': 'other', '4': 'take-profit'}
for t, n in j0.items():
    nm = nmap.get(t)
    if nm: CV.loc[CV.cls == 'buy-back: ' + nm, 'lots'] -= n * scale
j0lots = len(X[X.j == 0]) * scale
CV['tier_after'] = CV0.tier_after
CV.loc[CV.cls == 'buy-back: roll-out', 'tier_after'] = 2 if roll_met else 3; CV.loc[CV.cls == 'buy-back: roll-out', 'note'] = f'timing gate {"met" if roll_met else "not met"}: AUC {pre.auc:.3f} with the sale clock'
CV.loc[CV.cls == 'long buy: opening (<= 09:20)', 'tier_after'] = 2; CV.loc[CV.cls == 'long buy: opening (<= 09:20)', 'note'] = 'clock at 09:16:00; count ≈ sells of the 09:16 minute (rho 0.92); strike unresolved'
CV = pd.concat([CV, pd.DataFrame([dict(cls='buy-back: opening minute (09:15)', lots=j0lots, share=0, tier_before=np.nan, tier_after=3, note='the stop applied at the first print, partial take; ranking AUC 0.85 but CI 0.75-0.91, boosting 0.70')])], ignore_index=True)
CV['share'] = CV.lots / TOT   # the opening-minute lots were counted inside the other buy-back types before (cycle-stop 73, roll-out 198, burst member 95 lots): 'before' is taken straight from D0_BURST_LONG
cov = lambda col: {t: float(CV[CV[col] == t].share.sum()) for t in (1, 2, 3, 4)}; ca = cov('tier_after'); cb = {t: float(CV0[CV0.tier_after == t].share.sum()) for t in (1, 2, 3, 4)}; CV.round(4).to_csv(f'{OUT}/bl_d0z_coverage.csv', index=False)
# ---- figure
fig, ax = plt.subplots(2, 2, figsize=(14, 9)); bins = [0, 0.8, 1.0, 1.2, 1.4, 1.6, 5]; lab = ['<0.8', '0.8-1.0', '1.0-1.2', '1.2-1.4', '1.4-1.6', '>=1.6']; LL['bin'] = pd.cut(LL.ro, bins, labels=lab); g = LL.groupby('bin').taken.agg(['mean', 'size'])
ax[0, 0].bar(lab, 100 * g['mean'], color='#3d6b5a'); [ax[0, 0].text(i, 100 * m + 1.5, f'n={n}', ha='center', fontsize=8) for i, (m, n) in enumerate(zip(g['mean'], g['size']))]; ax[0, 0].set_xlabel('carried lot: price at the first print ÷ its entry'); ax[0, 0].set_ylabel('% bought back in the opening minute'); ax[0, 0].set_title('Opening buy-backs: the stop at the first print (partial)')
s = SQ.copy().iloc[::-1]; y = np.arange(len(s)); ax[0, 1].hlines(y, s.q25, s.q75, color='#3d6b5a', lw=6, alpha=.5); ax[0, 1].plot(s.first_s_median, y, 'k|', ms=14, label='median of first order'); ax[0, 1].plot(s.all_orders_median_s, y, 'o', color='#c05621', label='median of all orders'); ax[0, 1].set_yticks(y); ax[0, 1].set_yticklabels(s.klass); ax[0, 1].set_xlabel('seconds after 09:15:00 (bar = IQR of all orders)'); ax[0, 1].set_title('The opening sequence'); ax[0, 1].legend(fontsize=8); ax[0, 1].set_xlim(0, 180)
rng = np.random.default_rng(0); xj = CELLS.sells_j1 + rng.uniform(-.25, .25, len(CELLS)); yj = CELLS.lbuy + rng.uniform(-.25, .25, len(CELLS)); ax[1, 0].scatter(xj, yj, c=np.where(CELLS.und == 'NIFTY', '#2b6cb0', '#c05621'), alpha=.7); mx = max(CELLS.sells_j1.max(), CELLS.lbuy.max()); ax[1, 0].plot([0, mx], [0, mx], 'k:'); ax[1, 0].set_xlabel('lots sold in the 09:16 minute, per right'); ax[1, 0].set_ylabel('lots of long bought at 09:16:00'); ax[1, 0].set_title(f'Opening long buys follow the 09:16 sells (rho {OLG.rho.iloc[1]:.2f})')
sets = ['REF (ALL of D0_BURST_LONG)', 'REF + sale clock', 'REF + decayed/age', 'REF + sale clock + decayed/age']; w = 0.38
for k, o in enumerate(('roll-out', 'other')):
    z = RA[(RA.outcome == o) & RA.set.isin(sets)].set_index('set').loc[sets]; ax[1, 1].bar(np.arange(4) + (k - .5) * w, z.auc_loco, w, yerr=[z.auc_loco - z.lo, z.hi - z.auc_loco], color=['#2b6cb0', '#c05621'][k], capsize=2, label=o)
ax[1, 1].axhline(0.85, color='k', ls=':'); ax[1, 1].set_xticks(np.arange(4)); ax[1, 1].set_xticklabels(['reference', '+ sale\nclock', '+ decayed/\nage', '+ both'], fontsize=9); ax[1, 1].set_ylim(0.7, 0.92); ax[1, 1].set_ylabel('LOCO AUC (95% CI)'); ax[1, 1].set_title('Roll-out and "other": timing ranking'); ax[1, 1].legend(fontsize=8)
plt.tight_layout(); plt.savefig(os.path.join(FIG, 'bl_d0z_summary.png'), dpi=120); plt.close()
# ---- report
L = []; w_ = L.append; sq = SQ.set_index('klass'); lo = OL.set_index('feature'); rr = OR_.set_index('rule'); oc = OC.set_index('candidate'); olg = OLG.set_index('candidate'); comp = R2['opening_sell_composition_lots']
w_('# Algo 8 — D0: roll-out and "other" buy-backs, and the opening burst\n')
w_('*Plan `D0_OPEN_ROLL_PLAN.md`, written before the tests (the addendum lists the post-hoc steps). In-sample discovery on D0; every score is leave-one-cycle-out (LOCO) or forward. Figure: `figures/bl_d0z_summary.png`. Scripts `bl_d0z_*.py`.*\n')
w_('## 0. Result\n')
w_(f'**Coverage (rule found, or timing gate met on unseen cycles): {pc(cb[1]+cb[2],1)} → {pc(ca[1]+ca[2],1)} of D0 lots. The 90% target is still not reached.** Roll-out passes the gate; "other" does not; the opening burst is decoded in structure but not in its counts.\n')
w_('| tier | before | after |\n|---|---|---|'); [w_(f'| {t} {n} | {pc(cb[t])} | {pc(ca[t])} |') for t, n in ((1, 'rule found'), (2, 'timing/count gate met'), (3, 'ranked below the gate / indicative / same-minute only'), (4, 'unresolved'))]
w_('\n| question | answer | evidence |\n|---|---|---|')
w_(f'| **Roll-out buy-backs: above 0.85?** | **Yes, on the pre-registered set.** Adding the learned **sale clock** (does the timetable sell on this right in this, the next or the previous minute?) lifts AUC from {ref_roll.auc_loco:.3f} to **{pre.auc:.3f}** (CI {pre.lo:.3f}–{pre.hi:.3f}, forward {pre.forward:.3f}, within-cycle {pre.within_cycle:.3f}, placebo of the same set {pre.placebo:.3f}). Paired gain {gain.gain_over_REF:+.3f} (CI {gain.lo:+.3f} to {gain.hi:+.3f}). Gate met, with a thin margin (forward {pre.forward:.3f} against 0.80). | Observed |')
w_(f'| Why did it work? | **The label.** A roll-out is defined by a same-right sale within 60 s *after* the buy-back, and {pc(R1["audit_all_followed_chance"],0)} of buy-backs are followed by a sale by chance (roll-out lots: 100% by definition against {pc(AUD[AUD.t==6].followed_chance.iloc[0],0)} chance). The timetable tells when a sale is due, which is decision-time information. So the improvement is partly *predicting the timetable*, not a new buy-back reason. | Observed |')
w_(f'| **"Other" buy-backs: above 0.85?** | **No.** Best {oth.auc:.3f} (CI {oth.lo:.3f}–{oth.hi:.3f}, forward {oth.forward:.3f}); sale clock +{RA[(RA.outcome=="other")&(RA.set=="REF + sale clock")].auc_loco.iloc[0]-RA[(RA.outcome=="other")&RA.set.str.startswith("REF (")].auc_loco.iloc[0]:.3f}; decayed-lot / age features +{RA[(RA.outcome=="other")&(RA.set=="REF + decayed/age")].auc_loco.iloc[0]-RA[(RA.outcome=="other")&RA.set.str.startswith("REF (")].auc_loco.iloc[0]:.3f}; post-hoc class clock {othpost.auc:.3f}. "Other" is a residual by construction (no stop-loss, take-profit, partner, burst or following sale: only {pc(AUD[AUD.t==8].followed_real.iloc[0],1)} are followed by a sale against {pc(AUD[AUD.t==8].followed_chance.iloc[0],0)} chance). | Observed; stays below the gate |')
w_(f'| Did the two-stage product help? | No: roll-out {RA[(RA.outcome=="roll-out")&RA.set.str.startswith("two-stage")].auc_loco.iloc[0]:.3f}, other {RA[(RA.outcome=="other")&RA.set.str.startswith("two-stage")].auc_loco.iloc[0]:.3f}, both below the single-stage models. | Observed |')
w_(f'| **Opening burst: what is bought back?** | The **stop at the first print, applied partially.** Among carried lots (cycles without a stop at the open) the take rate rises from {pc(g["mean"].iloc[0],0)} below 0.8× entry to {pc(g["mean"].iloc[4],0)} at 1.4–1.6×. Price ÷ entry at the open ranks the lots at AUC {R2["single_auc_ci_ro"][0]:.3f} (CI {R2["single_auc_ci_ro"][1]:.3f}–{R2["single_auc_ci_ro"][2]:.3f}), within a cycle-and-right {lo.loc["price / entry at the first print (open)"].within_cycle_right_auc:.2f}; a boosted model is **worse** ({lo.loc["ALL lot features (LOCO boosting)"].pooled_auc:.2f}, forward {R2["forward_auc"]:.2f}). The best threshold rule (open ÷ entry ≥ {rr.loc["take every lot with open / entry >= theta"].theta_median:.1f}) has precision {rr.loc["take every lot with open / entry >= theta"].precision:.2f}, recall {rr.loc["take every lot with open / entry >= theta"].recall:.2f}. **Not gate-met.** | Observed |')
w_(f'| How many opening buy-backs? | Median {R2["k_median"]:.1f} lots per cycle and right (many zero; up to {int(LL.groupby(["cid", "cp"]).taken.sum().max())}). Best candidate: a fraction of the lots whose open price is ≥ 1.4× entry, exact {pc(oc.loc["median fraction x n_ro14"].exact,0)} against {pc(oc.loc["baseline: median of the other cycles"].exact,0)} for the baseline, error {oc.loc["median fraction x n_ro14"].mae:.1f} vs {oc.loc["baseline: median of the other cycles"].mae:.1f} lots, ρ {oc.loc["median fraction x n_ro14"].rho:.2f}. **Associated only** (ρ < 0.5). | Observed |')
w_(f'| **Opening sells** | In the first three minutes of cycles without a stop: {comp["sells"]} lots, of which scheduled waves {comp["sched"]} ({pc(comp["sched"]/comp["sells"],0)}), opening pairs {comp["opair"]} ({pc(comp["opair"]/comp["sells"],0)}), **opening solo {comp["osolo"]} ({pc(comp["osolo"]/comp["sells"],0)})**. No candidate predicts the count (best, carried shorts: exact {pc(OS.iloc[0].exact,0)}, error {OS.iloc[0].mae:.1f} vs baseline {OS.iloc[7].mae:.1f}, ρ {OS.iloc[0].rho:.2f}); the number sold is **not** tied to the number bought back (ρ {OS.iloc[2].rho:.2f}). | Observed; Unresolved |')
w_(f'| **Opening long buys** | **A clock event at 09:16:00 (median {sq.loc["body long buy"].first_s_median:.0f} s after the open, IQR {sq.loc["body long buy"].q25:.0f}–{sq.loc["body long buy"].q75:.0f}) whose size follows the sells of the 09:16 minute**: ρ {olg.loc["median ratio x sells_j1"].rho:.2f}, within 2 lots in {pc(olg.loc["median ratio x sells_j1"].within2,0)} of cycle-rights, error {olg.loc["median ratio x sells_j1"].mae:.1f} vs {olg.loc["baseline: median of the other cycles, same underlying"].mae:.1f} lots for the baseline (median ratio {R2["lbuy_over_sells_j1"]:.2f}, i.e. about one long lot per lot sold). Exact only {pc(olg.loc["median ratio x sells_j1"].exact,0)} (the baseline is exact {pc(olg.loc["baseline: median of the other cycles, same underlying"].exact,0)}: counts are narrow, 6–14). **Count rule found (approximate); strike still unresolved.** | Observed |')
w_(f'| Gap days | In the 4 cycles that stop at the open the stop module sends a median {GP.iloc[0]["stop module"]:.0f} lots and the hedge module {GP.iloc[0]["hedge other"]:.0f}; the body then sells {GP.iloc[0]["body sell"]:.0f} lots in the first three minutes (against {GP.iloc[1]["body sell"]:.0f} on other days) and buys {GP.iloc[0]["body long buy"]:.0f} long lots (against {GP.iloc[1]["body long buy"]:.0f}). | Observed |\n')
w_('### The opening in order (09:15:00 = 0 s)\n'); w_(SQ.round(1).to_markdown(index=False) + '\n')
w_('1. **0–10 s, gap days only:** stop module and hedge module liquidate the carried book at the first prints.\n2. **~11 s:** the stop applied to carried lots at the first print (partial), and the first opening sells (mostly solo, 70%).\n3. **~18–26 s:** the hedge controller releases wings freed by the buy-backs and buys wings for the new shorts.\n4. **09:16:00–09:16:09:** the opening long buys, sized to the lots sold in the 09:16 minute.\n')
w_('## 1. Roll-out and "other" (cell = cycle × minute × right)\n'); w_('### Label audit (share of in-scope buy-back lots followed by a same-right sale within 60 s)\n'); w_(AUD.round(3).to_markdown(index=False) + '\n'); w_('*Types: 3 stop-loss, 4 take-profit, 5 partner, 6 roll-out, 7 burst member, 8 other. Chance = the sale times shifted ±10 and ±15 minutes.*\n')
w_('### Timing gate\n'); w_(pd.concat([POST.assign(note='gate set: pre-registered R-H1 set (roll-out) / best pre-registered set (other); POST-HOC rows labelled')]).round(3).to_markdown(index=False) + '\n'); w_(RA.round(3).to_markdown(index=False) + '\n')
w_('*The tolerance outcome ("this or next minute") is a different, coarser class and is not a gate; its AUC is lower (roll-out 0.82, other 0.78) because its positives include neighbouring minutes.*\n')
w_('## 2. The opening burst\n'); w_('### Which carried lots are bought back at the first print (lot level)\n'); w_(OL.round(3).to_markdown(index=False) + '\n'); w_(OR_.round(3).to_markdown(index=False) + '\n')
w_(f'*{R2["lots_no_stop_open"]:,} carried lots in {R2["cycles"]} cycles without a stop at the open; {R2["taken_no_stop_open"]} bought back. LOCO boosting AUC {lo.loc["ALL lot features (LOCO boosting)"].pooled_auc:.3f} (CI {R2["loco_auc_ci"][0]:.2f}–{R2["loco_auc_ci"][1]:.2f}), forward {R2["forward_auc"]:.3f} on {R2["forward_taken"]} lots, placebo {R2["placebo_auc"]:.2f}. precision@m (the lots a ranking puts first that were really taken): high ÷ entry {R2["precision_at_m"]["rh"]:.2f}, open ÷ entry {R2["precision_at_m"]["ro"]:.2f}, chance {R2["chance_precision_at_m"]:.2f}.*\n')
w_('### How many bought back, per cycle and right\n'); w_(OC.round(3).to_markdown(index=False) + '\n'); w_('### Opening sells (minutes 0–2)\n'); w_(OS.round(3).to_markdown(index=False) + '\n'); w_('### Opening long buys\n'); w_(OLG.round(3).to_markdown(index=False) + '\n'); w_('### Gap days vs other days (median lots per cycle, minutes 0–2)\n'); w_(GP.to_markdown(index=False) + '\n')
w_('## 3. Coverage by class\n'); w_(CV[['cls', 'lots', 'share', 'tier_before', 'tier_after', 'note']].round(4).to_markdown(index=False) + '\n')
w_('### What is still outside 90%\n'); w_('| class | share of D0 lots | tier | why |\n|---|---|---|---|')
for r in CV[CV.tier_after >= 3].sort_values('share', ascending=False).head(12).itertuples(): w_(f'| {r.cls} | {pc(r.share)} | {int(r.tier_after)} | {r.note} |')
w_(f'\nTiers 3 and 4 total {pc(ca[3]+ca[4])}; reaching 90% needs {pc(0.9-ca[1]-ca[2])} more. The pieces are small and mostly need the tick path (counts, exact seconds, which lots) or same-minute information.\n')
w_('## 4. Adversarial read\n')
w_('* **The roll-out gain is real but modest and partly the label.** AUC 0.857 against a gate of 0.85, forward 0.824. It depends on a timetable learned on training cycles (a new timetable version breaks it: `D0_FULL_AUC`). It was one of four pre-registered sets; the pre-registered R-H1 set is the one gated.')
w_('* **"Other" is a residual, not a mechanism.** It is defined by the absence of other reasons and of a following sale, so a high AUC would mean predicting the absence of everything else. Its 0.80 is a ranking of "unexplained buy-backs", 2.0% of D0 lots.')
w_(f'* **The opening burst is explained in structure, not in counts.** The stop at the first print and the 09:16:00 long buys are clear; how many opening lots are sold, how many carried lots are taken, and which strikes the longs use are not recovered. With 26 cycles and 200 opening buy-backs the lot-level numbers are noisy (CI of the open-ratio AUC {R2["single_auc_ci_ro"][1]:.2f}–{R2["single_auc_ci_ro"][2]:.2f}).')
w_('* **Coverage is not accuracy.** The free-run lot F1 (0.39–0.45) is unchanged: nothing found here is a rule the simulator can execute apart from the opening long count (which needs the sells it follows).')
w_('* **In-sample discovery on 32 cycles from one period;** nothing here was run on a 3-year history.\n')
w_('## Addendum — post-hoc steps (not pre-registered)\n* Class-specific clocks (learned share of other cycles with a roll-out or an "other" buy-back in the minute ±1) were added after "other" stayed below the gate: they lift "other" to 0.808 (still not met) and leave roll-out unchanged.\n* The roll-out gate is taken on the **pre-registered R-H1 set** with its own placebo (computed after the first run only for the best set).\n* A bootstrap CI for the single-feature opening AUC and the fixed rounding of the count baseline were added after the first run (the baseline had been left unrounded and showed 0% exact).\n* **Coverage correction:** `D0_BURST_LONG` gave the minute-0 buy-backs (cells at j = 0, outside its panel) the gate of j ≥ 1 cells; they are now a separate class (0.9% of D0 lots, tier 3).\n')
